contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        (uint u0, uint b0) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint cBalBefore = address(c).balance;

        c.Put{value: amount}(lockTime); if (__ESBMC_reverted()) return;

        uint cBalAfter = address(c).balance;
        uint receivedByC = cBalAfter - cBalBefore;

        (uint u1, uint b1) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        assert((b1 + cBalAfter) == (b0 + cBalBefore + receivedByC));
    }

    receive() external payable {}
}

