pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 lockTime, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 u0;
        uint256 b0;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { u0 = __r0; b0 = __r1; } catch { return; }
        uint cBalBefore = address(c).balance;
        try c.Put{value: amount}(lockTime) {} catch { return; }
        uint cBalAfter = address(c).balance;
        uint receivedByC = cBalAfter - cBalBefore;
        uint256 u1;
        uint256 b1;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { u1 = __r0; b1 = __r1; } catch { return; }
        assertTrue((b1 + cBalAfter) == (b0 + cBalBefore + receivedByC));
    }

    function testFuzz_run(uint256 lockTime, uint256 amount) public {
        _run(lockTime, amount);
    }

    receive() external payable {}
}
